uses:
systemctl: T=${JSON.stringify(T)}
PATH="$T/bin:$PATH"
as_root() { :; }
home_of() { echo "$T/homes/$1"; }
user_exists() { [ -e "$T/users/$1" ]; }
unit_active() { systemctl is-active -q "$1"; }
# The files here are this test's: only the link check is left (find -user would need the real users).
file_owned_by() { [ -f "$1" ] && [ ! -L "$1" ]; }
MACHINE_SUDOERS="$T/sudoers-machine" HUB_UNIT="$T/hub.service" CLAUDE_ACCOUNT_DIR="$T/var" CLAUDE_ACCOUNT_LOCK="$T/lock" MACHINE_CHANGES="$T/machine-changes.jsonl"
MINUTE=1 SWITCH_POLL=0.05
`,

systemd: for (const tool of ['logger', 'systemd-run', 'journalctl']) exe(tool, `#!/usr/bin/env bash
echo "${tool} $*" >> ${JSON.stringify(join(T, 'calls'))}
exit 1
`);

journalctl: for (const tool of ['logger', 'systemd-run', 'journalctl']) exe(tool, `#!/usr/bin/env bash
echo "${tool} $*" >> ${JSON.stringify(join(T, 'calls'))}
exit 1
`);

systemctl: T=${JSON.stringify(T)}
echo "systemctl $*" >> "$T/calls"
u="\${@: -1}"; a="$T/units/$u.active"; d="$T/units/$u.drain"
case "$1" in
is-active)
[ -e "$a" ] || exit 3
if [ -e "$d" ]; then n="$(cat "$d")"; if [ "$n" -le 1 ]; then rm -f "$a" "$d"; exit 3; fi; echo $((n - 1)) > "$d"; fi
exit 0 ;;
kill) [ -e "$a" ] || exit 1; if [ -e "$T/units/$u.stuck" ]; then echo 999999 > "$d"; else echo 3 > "$d"; fi ;;
stop) rm -f "$a" "$d" ;;
start) [ -e "$T/units/$u.nostart" ] && exit 1; touch "$a" ;;
*) exit 64 ;;
esac
`);

journalctl: if (file === 'journalctl') return `${'x'.repeat(6000)}
worklane[1]: Failed to execute /usr/local/bin/worklane: Permission denied
GH_TOKEN=ghs_${'a'.repeat(36)}
`;

loginctl: writeFileSync(join(dir, 'lib.sh'), `source ${JSON.stringify(join(m.s, 'lib.sh'))}
ensure_user() { touch "$T/users/$1"; }
ensure_group() { :; }
ensure_member() { :; }
install() { mkdir -p "$T/srv/$name"; }
loginctl() { :; }
install_sudoers() { echo "$1" >> "$T/instance-sudoers"; }
`);
